import pandas as pd, numpy as np, re
from statsmodels.tsa.filters.hp_filter import hpfilter

def get_series(path):
    df=pd.read_excel(path, header=None)
    annual={}
    for i,v in enumerate(df.iloc[:,0].astype(str)):
        m=re.match(r'^\s*(\d{4})\.$', v)
        if m:
            annual[int(m.group(1))]=float(df.iloc[i,1])
    qvals=[]
    for i,v in enumerate(df.iloc[:,0].astype(str)):
        if '2024:' in v:
            qvals.append(float(df.iloc[i,1]))
    annual[2024]=sum(qvals)/len(qvals)
    return pd.Series(annual).sort_index()

pce=get_series('/root/ERP-2025-table10.xls')
pfi=get_series('/root/ERP-2025-table12.xls')
cpi=pd.read_excel('/root/CPI.xlsx', header=None, index_col=0).iloc[:,0]
real_pce=pce/cpi
real_pfi=pfi/cpi
cyc_pce=hpfilter(np.log(real_pce), lamb=100)[0]
cyc_pfi=hpfilter(np.log(real_pfi), lamb=100)[0]
print('n',len(cyc_pce),len(cyc_pfi))
print(cyc_pce.corr(cyc_pfi))
